'use strict';
const ACADEMY_UI6={crewView,peopleView,bakeryView,bind,help,digestDestination6,performanceDetail5,crewRecruitDialog5,hireDialog,executiveDialog5,financeView};
let crewTab6='teams',academyRole6='barista';
function academyTabs6(){return `<div class="actions section-tabs" role="group" aria-label="Týmy a vzdělávání"><button class="${crewTab6==='teams'?'primary':'soft'}" data-crew-tab6="teams">Týmy a směny</button><button class="${crewTab6==='academy'?'primary':'soft'}" data-crew-tab6="academy">Vlastní akademie</button></div>`;}
crewView=function(){return academyTabs6()+(crewTab6==='academy'?academyView6():ACADEMY_UI6.crewView());};
function academyView6(){const a=state.academy6,f=a.facility,q=academyBuyQuote6(),active=a.courses.filter(c=>c.status==='studying'),last=a.last,cfg=ACADEMY_COURSES6[academyRole6];return `<p class="intro">Připrav baristy, pekaře a vedoucí ještě před expanzí. Akademie školí volné kandidáty; absolvent si ponechá jméno, osobnost i dovednosti při skutečném náboru.</p>${!f?`<section class="card"><h2>Vybudovat vlastní akademii</h2>${rows([['Školicí vybavení',money(q.cost)],['Prostory v centrále',q.needs+' míst · nyní volných '+q.seats],['Týdenní provoz',money(q.weekly)+' + školitel, odvody a odpisy'],['Předpoklady','Vlastní kavárna a obsazené HR']])}<p class="sub">Vybavení je investice s odpisem 1 000 Kč za týden po dobu pěti let. Nábor školitele stojí 20 000 Kč. Kurzy se platí zvlášť; kapacita je osm současných kandidátů.</p><div class="actions"><button class="primary" id="academyBuy6" ${!q.eligible||state.over||q.cash<q.cost?'disabled':''}>Prověřit pořízení akademie</button><button class="soft" data-goto="hq">Sídlo a HR</button></div></section>`:`<div class="report-overview5">${metric('VE VÝCVIKU',active.length+' / 8','Baristé 2 · pekaři 3 · vedoucí 4 týdny')}${metric('ŠKOLITEL',esc(f.manager?.name||'Neobsazeno'),f.manager?'Hrubá mzda '+money(f.manager.salary)+' / týden':'Najmi volného vedoucího')}${metric('TÝDENNÍ PROVOZ',money(academyOperating6()+(f.manager?.salary||0)*ECONOMY_RULES6.employer),'Včetně odvodů; odpis navíc do výsledku')}${metric('ABSOLVENTI MINULE',last?last.completed.length:'—',last?'Uzavřený T'+last.week:'Čeká na skutečný tah')}</div><section class="card"><div class="card-head"><h2>Školitel a provoz</h2><span class="badge">${f.enabled?'Výcvik povolen':'Pozastaveno'}</span></div><p class="sub">Školitel zvyšuje účinek kurzu podle vedení lidí a produktové dovednosti při zápisu. Dovednost kandidáta naroste až po dokončení. Pozastavení, chybějící školitel nebo HR zastaví čas výcviku; provoz a mzda pokračují.</p><div class="fields">${field('Volný vedoucí jako školitel',`<select id="academyTrainer6">${state.talents.filter(p=>!academyBusy6(p.pid)).map(p=>option(p.pid,p.name+' · '+money(p.salary)+'/týden',null)).join('')}</select>`)}</div><div class="actions"><button class="soft" id="academyTrainerHire6" ${!state.talents.some(p=>!academyBusy6(p.pid))||state.over?'disabled':''}>${f.manager?'Prověřit výměnu školitele':'Prověřit nábor školitele'}</button><button class="soft" id="academyEnabled6" ${state.over?'disabled':''}>${f.enabled?'Pozastavit výcvik':'Obnovit výcvik'}</button>${f.manager?`<button class="quiet" data-person-profile6="${f.manager.pid}">Profil školitele</button>`:''}<button class="soft" id="academyReport6">Otevřít report akademie</button></div></section><section class="card" style="margin-top:24px"><h2>Nový kurz</h2><div class="fields">${field('Role kandidáta',`<select id="academyRole6">${Object.entries(ACADEMY_COURSES6).map(([k,c])=>option(k,c.name,academyRole6)).join('')}</select>`)}${field('Volný kandidát',`<select id="academyCandidate6">${academyCandidates6(academyRole6).filter(p=>!academyBusy6(p.pid)).map(p=>option(p.pid,p.name+' · '+Object.entries(cfg.skills).map(([k,n])=>n+' '+number((academyRole6==='manager'?p.strength:p.skills)[k],0)).join(' / '),null)).join('')}</select>`)}${field('Dovednost',`<select id="academySkill6">${Object.entries(cfg.skills).map(([k,n])=>option(k,n,null)).join('')}</select>`)}</div><div id="academyQuote6" class="sub"></div><button class="primary" id="academyEnroll6" ${!f.enabled||!f.manager||!state.departments.hr||active.length>=8||state.over?'disabled':''}>Prověřit zápis</button><p class="sub">Školné se platí při zápisu a při zrušení se nevrací. Kandidát během kurzu nemůže nastoupit do práce. Zobrazení nabídky, změny výběru a zrušení dialogu nic neplatí.</p></section><section class="card" style="margin-top:24px"><h2>Probíhající výcvik</h2>${active.map(c=>`<article class="vote"><div><strong>${esc(c.name)} · ${ACADEMY_COURSES6[c.role].name}</strong><small>${ACADEMY_COURSES6[c.role].skills[c.skill]} · zbývá ${c.remaining} z ${c.weeks} skutečných týdnů · ${c.paused} týdnů přerušení<br>${c.before} → ${c.before+c.gain} po dokončení · zaplaceno ${money(c.cost)}</small></div><button class="quiet mini" data-academy-cancel6="${c.id}" ${state.over?'disabled':''}>Zrušit kurz</button></article>`).join('')||empty('Žádný kandidát právě nestuduje.')}</section><section class="card" style="margin-top:24px"><h2>Dokončené a zrušené kurzy</h2>${a.courses.filter(c=>c.status!=='studying').slice().reverse().map(c=>`<div class="news"><div><strong>${esc(c.name)} · ${c.status==='completed'?'Absolvoval/a':'Zrušeno'} T${c.finished}</strong><p class="sub">${ACADEMY_COURSES6[c.role].skills[c.skill]} ${c.before}${c.status==='completed'?' → '+c.actual:' · bez změny dovednosti'} · ${money(c.cost)} školné</p>${peopleAll6().some(x=>x.person.pid===c.pid)?`<button class="quiet mini" data-person-profile6="${c.pid}">Profil a historie</button>`:''}</div></div>`).join('')||empty('Výsledky se objeví až po výcviku.')}<div class="actions"><button class="soft" data-crew-tab6="teams">Nabrat baristu do týmu</button><button class="soft" data-goto="people">Nabrat vedoucího</button><button class="soft" data-goto="bakery">Přijmout pekaře</button></div></section>`}`;}
function academyConfirm6(title,description,quote,run){show(`<h2>${esc(title)}</h2>${description}<div class="actions"><button class="primary" id="academyConfirm6" ${state.over||quote.cash<(quote.cost??quote.fee??0)?'disabled':''}>Potvrdit a zaplatit</button><button class="soft" id="academyCancel6">Zrušit</button></div>`);el('academyCancel6').onclick=()=>el('modal').close();el('academyConfirm6').onclick=()=>act(()=>{run();el('modal').close();render()});}
function academyRefreshQuote6(){try{const q=academyCourseQuote6(academyRole6,el('academyCandidate6').value,el('academySkill6').value);el('academyQuote6').textContent=q.weeks+' skutečné týdny · '+money(q.cost)+' školné · '+q.before+' → '+(q.before+q.gain)+' bodů po dokončení.';}catch(e){el('academyQuote6').textContent=e.message;}}
financeView=function(){return '<div class="actions"><button class="soft" data-academy-open6>Školné a provoz vlastní akademie</button></div>'+ACADEMY_UI6.financeView().replace('Vývoj IT','IT a provoz akademie');};
peopleView=function(){return '<div class="actions"><button class="soft" data-academy-open6>Vlastní akademie · příprava talentů</button></div>'+ACADEMY_UI6.peopleView();};
bakeryView=function(){const html=ACADEMY_UI6.bakeryView().replace('Pekaři (nábor 8 000 Kč / člověk)','Pekaři na směnu (nábor 8 000 Kč / člověk)'),b=bakeryById5(selectedBakery5),team=b&&bakeryTeam6(b.id);return html+(team?`<section class="card" style="margin-top:24px"><div class="card-head"><h2>${esc(b.name)} · konkrétní pekaři</h2><button class="soft" data-academy-open6>Vlastní akademie</button></div><p class="sub">${b.staff} lidí na každou z ${b.shifts} směn = ${team.people.length} skutečných smluv. Šest osmihodinových směn na osobu znamená 40 běžných hodin a 8 hodin s příplatkem 25 %. Provoz včetně týmu a odvodů ${money(bakeryFixed5(b))}/týden. Rychlost mění kapacitu, řemeslo a přesnost mění kvalitu nových šarží; dřívější zásoby se nepřepíší.</p><div class="table-scroll"><table class="data"><thead><tr><th>Pekař</th><th>Rychlost</th><th>Řemeslo</th><th>Přesnost</th><th>Mzda s odvody / týden</th></tr></thead><tbody>${team.people.map(p=>`<tr><td><button class="quiet mini" data-person-profile6="${p.pid}">${esc(p.name)}</button></td><td>${number(p.skills.speed,1)}</td><td>${number(p.skills.craft,1)}</td><td>${number(p.skills.safety,1)}</td><td>${money(b.wage*p.payFactor*1.25*cityWageFactor6(b.city)*(1+ECONOMY_RULES6.employer))}</td></tr>`).join('')}</tbody></table></div><h3>Kandidáti a absolventi</h3><p class="sub">Nový kandidát nahradí pekaře s nejnižším řemeslem; stávající člověk se vrátí na trh práce. Počet smluv se nemění. Nabíráš konkrétní osobu za jednorázový poplatek a týdenní mzdu.</p>${state.academy6.bakerCandidates.map(p=>`<div class="vote"><div><strong>${esc(p.name)}</strong><small>Rychlost ${number(p.skills.speed,0)} · řemeslo ${number(p.skills.craft,0)} · přesnost ${number(p.skills.safety,0)}${p.academy6?.length?' · absolvent akademie':''}${academyBusy6(p.pid)?' · ve výcviku':''}</small></div><button class="soft mini" data-baker-hire6="${p.pid}" ${academyBusy6(p.pid)||state.over?'disabled':''}>Prověřit nábor</button></div>`).join('')}</section>`:'');};
digestDestination6=function(item){if(item.key.startsWith('academy-finished-')||item.view==='crew'&&/akademi|školitel/i.test(item.title))crewTab6='academy';ACADEMY_UI6.digestDestination6(item);};
performanceDetail5=function(id){ACADEMY_UI6.performanceDetail5(id);if(reportKind5==='academy'&&el('reportManage5'))el('reportManage5').onclick=()=>{crewTab6='academy';el('modal').close();goto('crew');};};
bind=function(){ACADEMY_UI6.bind();on('[data-crew-tab6]',b=>{crewTab6=b.dataset.crewTab6;goto('crew')});on('[data-academy-open6]',()=>{crewTab6='academy';goto('crew')});const safe=fn=>{try{fn()}catch(e){toast(e.message)}};
 if(el('academyBuy6'))el('academyBuy6').onclick=()=>safe(()=>{const q=academyBuyQuote6();academyConfirm6('Vybudovat akademii?',rows([['Investice',money(q.cost)],['Po zaplacení',money(q.cash-q.cost)],['Prostory',q.needs+' míst'],['Další náklady','Provoz 3 000 Kč/týden, školitel a kurzy zvlášť']]),q,()=>buyAcademy6(q));});
 if(el('academyTrainerHire6'))el('academyTrainerHire6').onclick=()=>safe(()=>{const pid=el('academyTrainer6').value,q=academyTrainerQuote6(pid);academyConfirm6('Najmout školitele?',rows([['Nábor',money(q.fee)],['Hrubá mzda / týden',money(q.salary)],['Odvody / týden',money(q.salary*ECONOMY_RULES6.employer)],['Po zaplacení',money(q.cash-q.fee)]])+'<p class="sub">Při výměně zůstává bývalý školitel volným kandidátem se stejnými dovednostmi.</p>',q,()=>hireAcademyTrainer6(pid,q));});
 if(el('academyEnabled6'))el('academyEnabled6').onclick=()=>act(()=>setAcademyEnabled6(!state.academy6.facility.enabled),'Stav výcviku uložen.');
 if(el('academyRole6'))el('academyRole6').onchange=()=>{academyRole6=el('academyRole6').value;render()};
 if(el('academyCandidate6')){el('academyCandidate6').onchange=el('academySkill6').onchange=academyRefreshQuote6;academyRefreshQuote6();}
 if(el('academyEnroll6'))el('academyEnroll6').onclick=()=>safe(()=>{const role=academyRole6,pid=el('academyCandidate6').value,skill=el('academySkill6').value,q=academyCourseQuote6(role,pid,skill);academyConfirm6('Zapsat '+q.name+'?',rows([['Kurz',ACADEMY_COURSES6[role].skills[skill]],['Délka',q.weeks+' skutečné týdny'],['Školné',money(q.cost)],['Výsledek po dokončení',q.before+' → '+(q.before+q.gain)],['Po zaplacení',money(q.cash-q.cost)]])+'<p class="sub">Během výcviku je kandidát rezervovaný. Zrušení po zápisu nevrací školné.</p>',q,()=>enrollAcademy6(role,pid,skill,q));});
 on('[data-academy-cancel6]',b=>confirmAction('Zrušit probíhající kurz?','Dovednosti se nezvýší, zaplacené školné se nevrací. Kandidát se uvolní pro nábor.',()=>cancelAcademyCourse6(b.dataset.academyCancel6),'Zrušit kurz'));
 if(el('academyReport6'))el('academyReport6').onclick=()=>{reportKind5='academy';goto('performance')};
 on('[data-baker-hire6]',b=>safe(()=>{const pid=b.dataset.bakerHire6,bakery=selectedBakery5,q=bakerHireQuote6(pid,bakery),old=bakeryTeam6(bakery).people.find(p=>p.pid===q.replace);academyConfirm6('Přijmout '+academyPerson6('baker',pid).name+'?',rows([['Nábor a odstupné',money(q.fee)],['Nová mzda s odvody / týden',money(q.weekly)],['Nahrazený pekař',old.name],['Po zaplacení',money(q.cash-q.fee)]]),q,()=>hireAcademyBaker6(pid,bakery,q));}));
 if(el('bakerySave5'))el('bakerySave5').onclick=()=>safe(()=>{const n=id=>Number(el(id).value),data={staff:n('bakeryStaff5'),shifts:n('bakeryShifts5'),budget:n('bakeryBudget5'),reserve:n('bakeryReserve5'),auto:el('bakeryAuto5').checked,maintenance:el('bakeryMaintenance5').checked},b=bakeryById5(selectedBakery5),cost=bakeryHireFee6(b,data),heads=data.staff*data.shifts;confirmAction('Uložit provoz pekárny?',money(cost)+' za nábor nebo odstupné. '+heads+' skutečných zaměstnanců v '+data.shifts+' směnách, mzdy s odvody a přesčasy navíc každý týden.',()=>setBakery5(b.id,data));});
};
help=function(){ACADEMY_UI6.help();const p=document.createElement('p');p.textContent='Vlastní akademii najdeš v Týmech a HR jako podstránku. Vyžaduje šest volných míst v centrále, HR, vybavení a placeného školitele. Volní baristé studují dva týdny, pekaři tři a vedoucí čtyři. Absolventi si ponechají identitu a zlepšené dovednosti při náboru. Pekaři mají skutečné smlouvy pro každou výrobní směnu; rychlost mění kapacitu a řemeslo s přesností kvalitu budoucích šarží.';el('modalContent').append(p);};el('help').onclick=help;render();

function markAcademyReservations6(selector,property){document.querySelectorAll(selector).forEach(b=>{if(academyBusy6(b.dataset[property])){b.disabled=true;b.textContent='Ve výcviku';}});}
crewRecruitDialog5=function(){ACADEMY_UI6.crewRecruitDialog5();markAcademyReservations6('[data-barista-hire]','baristaHire');};
hireDialog=function(...args){ACADEMY_UI6.hireDialog(...args);markAcademyReservations6('[data-candidate]','candidate');};
executiveDialog5=function(...args){ACADEMY_UI6.executiveDialog5(...args);markAcademyReservations6('[data-executive-candidate]','executiveCandidate');};
